#!/usr/bin/env node

/**
 * Validates that no Markdown files exist in the repository root.
 *
 * This script enforces the repository boundaries rule: all .md files must be
 * placed in designated subdirectories (.github/specs/, .github/reports/, docs/, etc.)
 * and NOT in the repository root.
 *
 * SYSTEM-PROVISIONED BRANCHES:
 * This validator is designed for content validation, not branch naming validation.
 * For branch naming validation, use: npm run validate:branch-name
 *
 * Note: Claude Code session branches (e.g., claude/session-xyz, copilot/feature-xyz)
 * are auto-generated by development environment systems and are exempt from the
 * branch naming rules in a development context. However, before creating PRs on such
 * branches, rename them to follow the standard {type}/{scope}-{title} pattern
 * (e.g., docs/feature-name, feat/new-capability).
 *
 * Usage:
 *   node validate-no-root-md-files.cjs
 *   node validate-no-root-md-files.cjs --fix
 *
 * Exit codes:
 *   0 - No violations found (success)
 *   1 - Violations found (failure)
 */

const fs = require('fs');
const path = require('path');

// Allowed root-level files that are exceptions
const ALLOWED_ROOT_FILES = [
  'README.md',
  'CONTRIBUTING.md',
  'LICENSE.md',
  'CHANGELOG.md',
  'CODE_OF_CONDUCT.md',
  'SECURITY.md',
  '.github/CLAUDE.md',
  '.github/AGENTS.md',
];

// Files that should NOT be in root
const FORBIDDEN_ROOT_MD_PATTERNS = [
  /^PHASE\d+[A-Z_]*\.md$/,
  /^.*PROMPT\.md$/,
  /^.*REPORT.*\.md$/,
  /^.*PILOT.*\.md$/,
  /^SPEC.*\.md$/,
  /^.*SPECIFICATION.*\.md$/,
  /^TODO.*\.md$/,
  /^NOTES.*\.md$/,
  /^PLAN.*\.md$/,
  /^RESEARCH.*\.md$/,
];

function findRootMdFiles() {
  const repoRoot = process.cwd();
  const files = fs.readdirSync(repoRoot)
    .filter(file => file.endsWith('.md') && file !== 'README.md' && file !== 'CONTRIBUTING.md');

  return files.filter(file => {
    const fullPath = path.join(repoRoot, file);
    const stat = fs.statSync(fullPath);

    // Skip directories
    if (stat.isDirectory()) return false;

    // Check against allowed files
    if (ALLOWED_ROOT_FILES.includes(file)) return false;

    // Check against forbidden patterns
    return FORBIDDEN_ROOT_MD_PATTERNS.some(pattern => pattern.test(file));
  });
}

function main() {
  const violatingFiles = findRootMdFiles();

  if (violatingFiles.length === 0) {
    console.log('✅ No root-level Markdown files found. Repository boundaries are correct.');
    process.exit(0);
  }

  console.error('❌ REPOSITORY BOUNDARY VIOLATION: Markdown files found in repository root');
  console.error('');
  console.error('Files violating the boundary rule:');
  violatingFiles.forEach(file => {
    console.error(`  - ${file}`);
  });

  console.error('');
  console.error('Remediation: Move these files to their designated locations:');
  console.error('  • Specifications → .github/specs/{spec-slug}/');
  console.error('  • Reports → .github/reports/{category}/');
  console.error('  • Documentation → docs/');
  console.error('  • Project artefacts → .github/projects/active/{slug}/');
  console.error('  • Temporary drafts → .github/tmp/ (delete before PR)');
  console.error('');
  console.error('Reference: CLAUDE.md § Repository Boundaries, AGENTS.md § Repository File Placement');
  console.error('');

  process.exit(1);
}

// Export functions for testing
module.exports = {
  findRootMdFiles,
  ALLOWED_ROOT_FILES,
  FORBIDDEN_ROOT_MD_PATTERNS,
};

// Run main if executed directly (not required as a module)
if (require.main === module) {
  main();
}
